-- Display-only Dining Style Explore menu structure. Idempotent and independent from Food/MenuSelection.
CREATE TABLE IF NOT EXISTS dining_style_menu_categories (
  id BIGINT NOT NULL AUTO_INCREMENT,
  dining_style_id BIGINT NOT NULL,
  name VARCHAR(120) NOT NULL,
  display_order INT NOT NULL DEFAULT 0,
  available BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (id),
  UNIQUE KEY uq_dining_style_menu_category (dining_style_id, name),
  CONSTRAINT fk_dining_style_menu_category_style FOREIGN KEY (dining_style_id) REFERENCES dining_styles (id) ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS dining_style_menu_items (
  id BIGINT NOT NULL AUTO_INCREMENT,
  category_id BIGINT NOT NULL,
  name VARCHAR(160) NOT NULL,
  display_order INT NOT NULL DEFAULT 0,
  available BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (id),
  UNIQUE KEY uq_dining_style_menu_item (category_id, name),
  CONSTRAINT fk_dining_style_menu_item_category FOREIGN KEY (category_id) REFERENCES dining_style_menu_categories (id) ON DELETE RESTRICT
) ENGINE=InnoDB;

